  if (!role?.[0]) {
    return res.status(404).json({ success: false, error: "role not found" });
  }
  if (role[0].name === 'ADMIN' || role[0].name === 'DEVELOPER') {
    return res.status(403).json({ success: false, error: "base roles ADMIN and DEVELOPER cannot be deleted" });
  }
